{
	"html": {
		"value": "<div style="margin: -30px; min-height: 100vh; background: linear-gradient(135deg,#07142F,#163C78,#3B82F6); font-family: 'Segoe UI',sans-serif; color: white; overflow: hidden; position: relative;"><input id="navToggle" style="display: none;" type="checkbox"> <!-- NAVBAR -->
<div style="height: 80px; display: flex; align-items: center; justify-content: space-between; padding: 0 5%; background: rgba(6,14,35,.55); backdrop-filter: blur(14px);">
<div style="font-size: clamp(26px,4vw,38px); font-weight: 800;">Employee Vault</div>
<label class="hamburger" style="display: none; font-size: 32px; cursor: pointer; user-select: none;" for="navToggle"> ☰ </label> <!-- DESKTOP NAV -->
<div class="desktop-nav"><a href="/ev?id=dashboard"> Dashboard </a> <a href="#"> Departments </a> <a href="#"> Employee Directory </a> <a href="#"> Organization </a></div>
</div>
<!-- MOBILE MENU -->
<div class="mobile-nav"><a href="/ev?id=dashboard"> Dashboard </a> <a href="#"> Departments </a> <a href="#"> Employee Directory </a> <a href="#"> Organization </a></div>
<!-- HERO -->
<div style="height: calc(100vh - 80px); display: flex; justify-content: center; align-items: center; text-align: center; padding: 24px;">
<div style="width: 100%; max-width: 900px; padding: 0 20px;">
<h1 style="margin: 0; font-size: clamp(42px,12vw,92px); line-height: 1.05; font-weight: 900;">Employee <br>Vault</h1>
<p style="margin-top: 30px; font-size: clamp(16px,4vw,24px); line-height: 1.8; max-width: 720px; margin-left: auto; margin-right: auto; opacity: .92;">Manage employees, departments and reporting hierarchy across your organization</p>
<a style="display: inline-block; margin-top: 45px; padding: 18px 38px; font-size: clamp(15px,3vw,18px); border-radius: 14px; background: linear-gradient(90deg,#17C98A,#35D7A7); color: white; font-weight: bold; text-decoration: none; box-shadow: 0 12px 28px rgba(0,0,0,.2); cursor: pointer;" href="/ev?id=employee_directory"> Get Started </a></div>
</div>
</div>
<style>

*{

box-sizing:border-box;

}



/* DESKTOP */

.desktop-nav{

display:flex;

gap:48px;

align-items:center;

}

.desktop-nav a{

color:white;

text-decoration:none;

font-size:18px;

position:relative;

padding-bottom:8px;

cursor:pointer;

transition:.25s;

}

.desktop-nav a::after{

content:'';

position:absolute;

left:0;

bottom:0;

width:0;

height:3px;

background:#22C58E;

transition:.25s;

}

.desktop-nav a:hover::after{

width:100%;

}

.desktop-nav a:hover{

opacity:.9;

}



/* MOBILE */

.mobile-nav{

display:none;

background:#10254D;

flex-direction:column;

}

.mobile-nav a{

padding:22px;

text-align:center;

color:white;

text-decoration:none;

font-size:18px;

}

.mobile-nav a:hover{

background:#173C74;

}



/* RESPONSIVE */

@media(max-width:900px){

.desktop-nav{

display:none;

}

.hamburger{

display:block!important;

}

#navToggle:checked ~ .mobile-nav{

display:flex;

}

}



@media(min-width:901px){

.mobile-nav{

display:none!important;

}

}

</style>",
